"""Test block LogIn (Accounts): Log in with an email and a password, with the ways to sign up and to reset a forgotten password.

Generated by tools/blocks_from_app_blocks.py from the App Block card kit/blocks/accounts/LogIn.md and its markup
(kit/blocks/accounts/LogIn.html; source 56c114a887fa), with the vocabulary in
functional/blocks/spec.json. Do not edit: change the spec (or the App Block) and generate again.

Steps (e2e):
  Given I am on the log in page
  When I log in as {email} with {password}
  When I enter the email {email}
  When I enter the password {password}
  When I press Log In
  When I untick keep me logged in
  When I follow the forgot password link
  When I follow the sign up link
  Then I see the log in error
  Then the email field has {email}
  Then keep me logged in is ticked
  Then the log in form is in the {state} state
States (from the card): Empty, Field error, Sending, Wrong email or password, Too many tries, Offline, Success.
Checked by the state step: Empty, Field error, Sending, Wrong email or password, Too many tries, Offline.
"""
from __future__ import annotations

from functional import Registry
from functional import primitives as p

BLOCK = "LogIn"
ROUTE = "/login"
STATES = ["Empty", "Field error", "Sending", "Wrong email or password", "Too many tries", "Offline", "Success"]
DEFAULT_STATE = "Empty"
CHECKED_STATES = ["Empty", "Field error", "Sending", "Wrong email or password", "Too many tries", "Offline"]
DEMO = ["kit/blocks/accounts/LogIn.html"]
SELF_TEST = [
    "Given I am on the log in page",
    "Then the log in form is in the \"Empty\" state",
    "Then keep me logged in is ticked",
    "When I enter the email \"aiko@example.com\"",
    "Then the email field has \"aiko@example.com\"",
    "When I untick keep me logged in",
    "When I follow the sign up link",
    "Then the log in form is in the \"Empty\" state",
]

steps = Registry(block=BLOCK)


class LogIn:
    """The LogIn block on a page: its controls, found as a person finds them (role and name, label, text)."""

    def __init__(self, page, base_url: str = ""):
        self.page = page
        self.base_url = base_url

    def form(self):
        return p.control(self.page, css="#login-form", block=BLOCK)

    def email(self):
        return p.control(self.form(), label="Email", block=BLOCK)

    def password(self):
        return p.control(self.form(), label="Password", block=BLOCK)

    def remember(self):
        return p.control(self.form(), role="checkbox", name="Keep me logged in", block=BLOCK)

    def submit(self):
        return p.control(self.form(), role="button", name="Log In", block=BLOCK)

    def forgot(self):
        return p.control(self.form(), role="link", name="Forgot your password?", block=BLOCK)

    def signup(self):
        return p.control(self.form(), role="link", name="Sign Up", block=BLOCK)

    def error(self):
        return p.control(self.form(), css="#login-error", block=BLOCK)

    def invalid(self):
        return p.control(self.form(), css="[aria-invalid=\"true\"]", block=BLOCK)

    def expect_state(self, state: str) -> None:
        """Check one of the card's states: Empty, Field error, Sending, Wrong email or password, Too many tries, Offline."""
        b = self
        if state == "Empty":
            p.expect_value(b.email(), "")
            p.expect_value(b.password(), "")
            p.expect_hidden(b.error())
        elif state == "Field error":
            p.expect_visible(b.invalid().first)
        elif state == "Sending":
            p.expect_attribute(b.submit(), "aria-busy", "true")
        elif state == "Wrong email or password":
            p.expect_visible(b.error())
        elif state == "Too many tries":
            p.expect_text(b.error(), "Too many tries")
        elif state == "Offline":
            p.expect_text(b.error(), "offline")
        else:
            raise AssertionError(f"LogIn has no check for the state {state!r}; checked: " + ", ".join(CHECKED_STATES))


@steps.step("Given I am on the log in page", level="e2e")
def given_i_am_on_the_log_in_page(world):
    b = LogIn(world.page, getattr(world, "base_url", ""))
    p.goto(world.page, b.base_url + ROUTE)
    p.expect_visible(b.submit())


@steps.step("When I log in as {email} with {password}", level="e2e")
def when_i_log_in_as_email_with_password(world, email, password):
    b = LogIn(world.page, getattr(world, "base_url", ""))
    p.fill(b.email(), str(email))
    p.fill(b.password(), str(password))
    p.click(b.submit())


